def find_blocks(g):
    R,C=len(g),len(g[0]); blocks=[]
    for r in range(R-1):
        for c in range(C-1):
            if all(g[r+i][c+j]==2 for i in range(2) for j in range(2)):
                blocks.append((r,c))
    return blocks

def corners(g,b):
    r,c=b
    tl=(r-1,c-1); tr=(r-1,c+2); bl=(r+2,c-1); br=(r+2,c+2)
    return {'TL':tl,'TR':tr,'BL':bl,'BR':br}

def solve(inp):
    g=[row[:] for row in inp]; R,C=len(g),len(g[0])
    blocks=find_blocks(g)
    order=['TL','TR','BR','BL']  # clockwise
    news={}
    for b in blocks:
        cs=corners(g,b)
        vals={k:g[cs[k][0]][cs[k][1]] for k in cs}
        # colors move clockwise: new[T] = old[previous in cw order] = old[ccw neighbor]
        for i,k in enumerate(order):
            prev=order[(i-1)%4]
            news[cs[k]]=vals[prev]
    # clear old corner cells
    for b in blocks:
        for pos in corners(g,b).values():
            r0,c0=pos
            if 0<=r0<R and 0<=c0<C: g[r0][c0]=0
    # set new corners
    for pos,v in news.items():
        r0,c0=pos
        if 0<=r0<R and 0<=c0<C: g[r0][c0]=v
    # rays: each corner emits outward diagonal
    dirs={'TL':(-1,-1),'TR':(-1,1),'BL':(1,-1),'BR':(1,1)}
    for b in blocks:
        cs=corners(g,b)
        for k,pos in cs.items():
            r0,c0=pos; v=news[pos]
            dr,dc=dirs[k]; rr,cc=r0+dr,c0+dc
            while 0<=rr<R and 0<=cc<C:
                g[rr][cc]=v
                rr+=dr; cc+=dc
    return g

def diff(a,b):
    out=[]
    for r in range(max(len(a),len(b))):
        for c in range(max(len(a[r]),len(b[r]))):
            va=a[r][c] if r<len(a) and c<len(a[r]) else None
            vb=b[r][c] if r<len(b) and c<len(b[r]) else None
            if va!=vb: out.append(((r,c),va,vb))
    return out

